const number=(v)=>Number(v).toLocaleString('en-IN');
const date=(v)=>new Date(v+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const seed={warehouses:[{id:'WH-001',name:'Gachibowli',location:'Hyderabad, TS',address:'Plot 24, Financial District, Gachibowli, Hyderabad, Telangana 500032',status:'Active',stock:12840,dispatched:142,packing:28},{id:'WH-002',name:'Whitefield',location:'Bengaluru, KA',address:'42, Greenfield Residency, Whitefield, Bengaluru, Karnataka 560066',status:'Active',stock:9640,dispatched:98,packing:19},{id:'WH-003',name:'Kukatpally',location:'Hyderabad, TS',address:'12, Industrial Estate, Kukatpally, Hyderabad, Telangana 500072',status:'Active',stock:8200,dispatched:86,packing:14},{id:'WH-004',name:'Madhapur',location:'Hyderabad, TS',address:'18, Hitech City Road, Madhapur, Hyderabad, Telangana 500081',status:'Active',stock:7450,dispatched:72,packing:11},{id:'WH-005',name:'Electronic City',location:'Bengaluru, KA',address:'7, Phase 1, Electronic City, Bengaluru, Karnataka 560100',status:'Active',stock:6200,dispatched:64,packing:9},{id:'WH-006',name:'Velachery',location:'Chennai, TN',address:'32, Velachery Main Road, Chennai, Tamil Nadu 600042',status:'Inactive',stock:2800,dispatched:0,packing:0}],
customers:[['CUST-8842','Meera Nair','Hyderabad, TS',24,42500,'2025-01-23','Active'],['CUST-7721','Rahul Sharma','Bengaluru, KA',18,31200,'2025-03-10','Active'],['CUST-9901','Priya Verma','Bengaluru, KA',9,12800,'2025-01-21','Active'],['CUST-8560','Karthik Suraj','Bengaluru, KA',31,58900,'2024-09-14','Active'],['CUST-9103','Sneha Desai','Hyderabad, TS',12,18650,'2025-06-08','Active'],['CUST-9104','Anita Reddy','Hyderabad, TS',16,26400,'2025-04-12','Active'],['CUST-9105','Arjun Menon','Chennai, TN',7,9800,'2025-08-19','Active'],['CUST-9106','Neha Kapoor','Bengaluru, KA',4,6200,'2026-02-10','Inactive'],['CUST-9107','Vikram Rao','Hyderabad, TS',21,38600,'2024-12-05','Active'],['CUST-9108','Divya Iyer','Chennai, TN',8,14400,'2025-11-17','Active'],['CUST-9109','Rohan Patel','Bengaluru, KA',3,4200,'2026-07-20','Inactive'],['CUST-9110','Lakshmi Devi','Hyderabad, TS',14,22800,'2025-02-28','Active']].map((c,i)=>({id:c[0],name:c[1],location:c[2],orders:c[3],value:c[4],joined:c[5],status:c[6],email:c[1].toLowerCase().replaceAll(' ','.')+'@example.com',phone:'+91 90000 '+String(12000+i),address:c[2]})),
admins:[['ADM-001','Sriraj Yadav','Super Admin','WH-001'],['ADM-002','Priya Sharma','Warehouse Admin','WH-001'],['ADM-003','Rahul Verma','Warehouse Admin','WH-002'],['ADM-004','Akhil Kumar','Warehouse Admin','WH-003'],['ADM-005','Sana Ahmed','Warehouse Admin','WH-004'],['ADM-006','Deepak Rao','Warehouse Admin','WH-005'],['ADM-007','Nisha Reddy','Warehouse Admin','WH-002'],['ADM-008','Vivek Nair','Warehouse Admin','WH-006']].map((a,i)=>({id:a[0],name:a[1],role:a[2],warehouse:a[3],email:a[1].toLowerCase().replaceAll(' ','.')+'@example.com',phone:'+91 90000 '+String(13000+i),status:i===7?'Inactive':'Active',joined:'2025-01-15'})),activity:[{title:'Welcome to your people workspace',description:'Customer, warehouse and administrator sample records are ready to explore.',time:'2026-11-06T10:30:00.000Z',icon:'leaf'}]};
const STORAGE='veda-people-v1';let storageAvailable=true;let data;
try{const stored=localStorage.getItem(STORAGE);data=stored?JSON.parse(stored):structuredClone(seed);if(!data.customers||!data.admins||!data.warehouses||!data.activity)throw Error('Invalid data')}catch{data=structuredClone(seed)}
let view=['overview','customers','warehouses','admins','activity'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';let query='',statusFilter='All',locationFilter='All',page=1,sort='name';const pageSize=6;const app=document.querySelector('#app'),modal=document.querySelector('#modal');let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function save(title,description,type='users'){data.activity.unshift({title,description,time:new Date().toISOString(),icon:type});try{localStorage.setItem(STORAGE,JSON.stringify(data));storageAvailable=true}catch{storageAvailable=false}render();toast(storageAvailable?'Changes saved in this browser.':'Browser storage is unavailable. Changes last for this session.');}
function avatar(name,i=0){return `<span class="avatar ${['','orange','blue','purple'][i%4]}">${esc(initials(name))}</span>`}
function badge(s){return `<span class="badge ${s==='Inactive'?'inactive':s==='Pending'?'pending':''}"><i class="dot"></i>${esc(s)}</span>`}
function navButton(k,label){return `<button data-action="navigate" data-view="${k}" class="${view===k?'active':''}" ${view===k?'aria-current="page"':''}>${label}</button>`}
function stat(label,value,note,glyph,word=false){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(glyph)}</span></div><div class="stat-value ${word?'word':''}">${value}</div><div class="stat-note">${note}</div></div>`}
function getBest(){return [...data.warehouses].filter(w=>w.status==='Active').sort((a,b)=>b.dispatched-a.dispatched)[0]}
function warehouseCard(w){const team=data.admins.filter(a=>a.warehouse===w.id);return `<article class="warehouse-card"><div class="warehouse-title"><div class="warehouse-identity"><span class="warehouse-icon">${icon('warehouse')}</span><div><h3>${esc(w.name)}</h3><p>${esc(w.location)}</p></div></div>${badge(w.status)}</div><div class="warehouse-metrics"><div><label>Stock on hand</label><strong>${number(w.stock)} <span style="font-size:10px;font-weight:400;color:#7b8578">kg</span></strong></div><div><label>Dispatched today</label><strong>${w.dispatched}</strong></div><div><label>To be packed</label><strong>${w.packing}</strong></div></div><div class="warehouse-bottom"><div class="avatar-stack">${team.slice(0,3).map((a,i)=>avatar(a.name,i)).join('')}<span>${team.length} ${team.length===1?'administrator':'administrators'}</span></div><button class="arrow-button" data-action="details" data-kind="warehouse" data-id="${w.id}">View warehouse ${icon('arrow')}</button></div></article>`}
function filtered(kind){const list=kind==='customer'?data.customers:kind==='admin'?data.admins:data.warehouses;return list.filter(x=>{const hub=data.warehouses.find(w=>w.id===x.warehouse);const loc=x.location||hub?.location||'';const hay=[x.name,x.id,x.email,loc,x.role,hub?.name].join(' ').toLowerCase();return hay.includes(query.toLowerCase())&&(statusFilter==='All'||x.status===statusFilter)&&(locationFilter==='All'||loc===locationFilter)}).sort((a,b)=>sort==='recent'?(b.joined||'').localeCompare(a.joined||''):sort==='value'?(b.value||0)-(a.value||0):sort==='name'?a.name.localeCompare(b.name):0)}
function toolbar(kind){return `<div class="directory-toolbar"><div class="tabs" aria-label="Filter by status">${['All','Active','Inactive'].map(s=>`<button data-action="status" data-status="${s}" class="${statusFilter===s?'active':''}" aria-pressed="${statusFilter===s}">${s==='All'?'All '+(kind==='admin'?'administrators':kind==='warehouse'?'warehouses':'customers'):s}</button>`).join('')}</div><div class="filters"><label class="search">${icon('search')}<input id="search" type="search" aria-label="Search ${kind==='admin'?'administrators':kind==='warehouse'?'warehouses':'customers'}" placeholder="Search ${kind==='admin'?'administrators':kind==='warehouse'?'warehouses':'customers'}…" value="${esc(query)}"></label><button class="filter-button ${locationFilter!=='All'||sort!=='name'?'applied':''}" data-action="filters">${icon('filter')} Filters${locationFilter!=='All'?' · 1':''}</button></div></div>`}
function footer(total){const pages=Math.ceil(total/pageSize);return `<div class="table-footer"><span>${total?'Showing '+((page-1)*pageSize+1)+'–'+Math.min(page*pageSize,total)+' of '+total:'No matching records'}</span><div class="pagination"><button data-action="page" data-page="${page-1}" aria-label="Previous page" ${page<=1?'disabled':''}>${icon('left')}</button>${Array.from({length:pages},(_,i)=>`<button data-action="page" data-page="${i+1}" class="${page===i+1?'active':''}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-action="page" data-page="${page+1}" aria-label="Next page" ${page>=pages?'disabled':''}>${icon('chevron')}</button></div></div>`}
function empty(){return `<div class="empty">${icon('search')}<h3>No matches found</h3><p>Try another search or clear your filters.</p><button class="btn small" data-action="clear-filters">Clear filters</button></div>`}
function directory(kind='customer'){const list=filtered(kind);const title=kind==='admin'?'Administrator directory':'Customer directory';const rows=list.slice((page-1)*pageSize,page*pageSize);return `<section class="directory"><div class="directory-header"><div class="directory-title"><h2>${title}</h2><span class="count">${list.length}</span></div></div>${toolbar(kind)}${rows.length?`<div class="table-scroll"><table><thead><tr>${(kind==='admin'?['Administrator','Role','Warehouse','Status','Joined on','Action']:['Customer','Location','Orders','Lifetime value','Status','Joined on','Action']).map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map((x,i)=>`<tr><td><div class="person">${avatar(x.name,i)}<div><strong>${esc(x.name)}</strong><small>${esc(x.id)}</small></div></div></td>${kind==='admin'?`<td>${esc(x.role)}</td><td>${esc(data.warehouses.find(w=>w.id===x.warehouse)?.name||'Unassigned')}</td>`:`<td>${esc(x.location)}</td><td class="order-number">${x.orders} <span style="color:#88917f;font-size:10px">orders</span></td><td class="money">${money(x.value)}</td>`}<td>${badge(x.status)}</td><td>${date(x.joined)}</td><td><div class="row-action"><button data-action="details" data-kind="${kind}" data-id="${esc(x.id)}">View details ${icon('arrow')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty()}${footer(list.length)}</section>`}
function overviewContent(){
  const activeCustomers=data.customers.filter(x=>x.status==='Active').length;
  const activeAdmins=data.admins.filter(x=>x.status==='Active').length;
  const activeHubs=data.warehouses.filter(x=>x.status==='Active').length;
  const locations=new Set(data.warehouses.map(x=>x.location)).size;
  const members=data.warehouses.map(w=>data.admins.filter(a=>a.warehouse===w.id).length);
  const maxMembers=Math.max(1,...members);
  const ratio=data.customers.length?Math.round(activeCustomers/data.customers.length*100):0;
  return `<section class="bento" aria-label="Your people and network at a glance">
    <article class="harvest-card">
      <div class="harvest-top"><span class="eyebrow">${icon('leaf')} THE VEDA BHARATH NETWORK</span><span class="harvest-season">Rooted in tradition</span></div>
      <h2>Good people.<br>Shared growth.</h2>
      <p class="harvest-description">Bringing our customers, teams and<br>communities closer. Every day.</p>
      <div class="hero-chips"><button data-action="navigate" data-view="customers">${icon('users')} ${data.customers.length} customers</button><button data-action="navigate" data-view="warehouses">${icon('warehouse')} ${data.warehouses.length} warehouses</button><button data-action="navigate" data-view="admins">${icon('shield')} ${data.admins.length} administrators</button></div>
      <span class="harvest-label label-one">${icon('warehouse')} ${activeHubs} hubs, one connected network</span>
      <span class="harvest-label label-two"><span class="label-circle">${icon('leaf')}</span> Growing together</span>
      <button class="harvest-link" data-action="navigate" data-view="warehouses">Explore your network <span>${icon('arrow')}</span></button>
    </article>
    <aside class="network-card">
      <div class="bento-heading"><h2>Your network</h2><button class="round-link" data-action="navigate" data-view="warehouses" aria-label="View all warehouses">${icon('arrow')}</button></div>
      <div class="network-summary"><div><strong>${data.warehouses.length.toString().padStart(2,'0')}</strong><span>warehouses</span></div><span class="network-live"><span class="dot"></span> ${activeHubs} operational</span></div>
      <div class="hub-chart" role="img" aria-label="Administrators by warehouse: ${esc(data.warehouses.map((w,i)=>w.name+': '+members[i]).join(', '))}">${data.warehouses.map((w,i)=>`<div class="hub-column"><span>${members[i]}</span><div class="hub-bar-track"><div class="hub-bar ${w.status==='Inactive'?'bar-inactive':i===0?'bar-highlight':''}" style="height:${Math.max(4,members[i]/maxMembers*100)}%"></div></div><small>${esc(w.name.slice(0,3).toUpperCase())}</small></div>`).join('')}</div>
      <div class="chart-caption"><span class="dot"></span> Administrators by warehouse</div>
      <div class="network-list-heading"><h3>Warehouse directory</h3><span>${locations} cities</span></div>
      <div class="network-list">${data.warehouses.slice(0,3).map((w,i)=>`<button class="network-row" data-action="details" data-kind="warehouse" data-id="${w.id}"><span class="network-index">0${i+1}</span><span class="network-name"><strong>${esc(w.name)}</strong><small>${esc(w.location)}</small></span><span class="network-status ${w.status==='Inactive'?'off':''}" aria-label="${esc(w.status)}"></span>${icon('chevron')}</button>`).join('')}</div>
      <button class="network-all" data-action="navigate" data-view="warehouses">All warehouses ${icon('arrow')}</button>
    </aside>
    <article class="team-card">
      <div class="bento-heading"><h2>The people behind it</h2><button class="round-link" data-action="navigate" data-view="admins" aria-label="View administrators">${icon('arrow')}</button></div>
      <div class="team-value"><strong>${activeAdmins.toString().padStart(2,'0')}</strong><span>/ ${data.admins.length.toString().padStart(2,'0')}<small>active administrators</small></span></div>
      <div class="team-bottom"><div class="team-avatars">${data.admins.filter(x=>x.status==='Active').slice(0,4).map((a,i)=>avatar(a.name,i)).join('')}</div><button data-action="add" data-kind="admin">${icon('plus')} Add to your team</button></div>
      <span class="team-decoration" aria-hidden="true">${icon('leaf')}</span>
    </article>
    <article class="community-card">
      <div class="bento-heading"><h2>Our growing community</h2><button class="round-link" data-action="navigate" data-view="customers" aria-label="View customer directory">${icon('arrow')}</button></div>
      <div class="community-value"><strong>${data.customers.length.toString().padStart(2,'0')}</strong><span>customers<br>and counting</span></div>
      <p><span class="dot"></span> ${activeCustomers} active relationships</p>
      <div class="community-dial" style="--active-ratio:${ratio}%" role="img" aria-label="${ratio}% of customers are active"><div><span class="paddy-leaf" aria-hidden="true">${icon('leaf')}</span><span>${ratio}% <small>active</small></span></div></div>
    </article>
  </section><div class="overview-directory-heading"><span class="eyebrow">PEOPLE AT THE HEART OF IT ALL</span><p>Your customer relationships, in one place.</p></div>${directory()}`;
}
function render(){const titles={overview:['User management','Nurturing relationships. Connecting our people.'],customers:['Customers','Know your customers. Build lasting relationships.'],warehouses:['Warehouses','Manage your distribution network and the people behind it.'],admins:['Administrators','The team keeping your everyday operations moving.'],activity:['Workspace activity','A history of changes made in this browser.']};const [title,subtitle]=titles[view];app.innerHTML=`${storageAvailable?'':'<div class="storage-note">Browser storage is unavailable. Changes are saved for this session only.</div>'}<header class="topbar"><a class="brand" href="#overview" aria-label="Veda Bharath user management home"><span class="logo"><img src="assets/veda-logo.png" alt="Veda Bharath"></span><span class="brand-divider"></span><span class="brand-label">VEDA BHARATH<strong>People & places</strong></span></a><nav class="nav" aria-label="Main navigation">${navButton('overview','Overview')}${navButton('customers','Customers')}${navButton('warehouses','Warehouses')}${navButton('admins','Administrators')}</nav><div class="header-actions"><button class="icon-button" data-action="navigate" data-view="activity" aria-label="View workspace activity">${icon('bell')}</button><button class="profile-button" data-action="profile" aria-label="View administrator profile">${avatar('Sriraj Yadav')}<span><strong>Sriraj Yadav</strong>Super administrator</span></button></div></header><main class="main ${view==='overview'?'overview-main':''}"><div class="breadcrumb">Workspace ${icon('chevron')} <span>${view==='overview'?'Overview':title}</span></div><div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="page-actions">${view==='activity'?`<button class="btn" data-action="export">${icon('download')} Export activity</button>`:`<button class="btn" data-action="export">${icon('download')} Export</button><button class="btn ${view==='warehouses'?'primary':''}" data-action="add" data-kind="${view==='customers'?'customer':'warehouse'}">${icon('plus')} ${view==='customers'?'Add customer':'New warehouse'}</button>${view!=='customers'&&view!=='warehouses'?`<button class="btn primary" data-action="add" data-kind="admin">${icon('plus')} Create admin</button>`:''}`}</div></div>${view==='overview'?overviewContent():view==='customers'?directory():view==='admins'?directory('admin'):view==='warehouses'?`<section class="directory" style="margin-bottom:20px"><div class="directory-header"><div class="directory-title"><h2>Distribution hubs</h2><span class="count">${filtered('warehouse').length}</span></div></div>${toolbar('warehouse')}</section><div class="warehouses full-grid">${filtered('warehouse').map(warehouseCard).join('')||empty()}</div>`:`<section class="directory"><div class="directory-header" style="padding-bottom:18px"><div class="directory-title"><h2>Recent activity</h2><span class="count">${data.activity.length}</span></div></div><div class="activity-list">${data.activity.map(a=>`<article class="activity-row"><span class="stat-icon">${icon(a.icon)}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.description)}</p></div><time datetime="${esc(a.time)}">${new Date(a.time).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} IST</time></article>`).join('')}</div></section>`}<footer class="footnote"><span>${icon('leaf')} Rooted in tradition. Connected through people.</span><span><span class="dot" style="color:#a88640"></span> Sample workspace · Changes saved in this browser <button class="btn text" data-action="about" style="font-size:10px;padding:0 0 0 5px" aria-label="About this sample workspace">${icon('info')}</button></span></footer></main>`;}
function navigate(next){view=next;query='';statusFilter='All';locationFilter='All';page=1;sort='name';location.hash=next;render();window.scrollTo({top:0,behavior:'instant'})}
function openModal(title,subtitle,body,footer=''){modal.innerHTML=`<div class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!modal.open)modal.showModal();document.body.style.overflow='hidden'}
modal.addEventListener('close',()=>{document.body.style.overflow=''});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
const field=(label,name,value='',type='text',required=true)=>`<div class="field"><label for="field-${name}">${label}${required?' *':''}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${name==='phone'?'pattern="[+0-9() -]{7,20}" title="Enter a valid phone number (7–20 characters)."':''} maxlength="${name==='phone'?20:120}"></div>`;
function entity(kind,id){return (kind==='customer'?data.customers:kind==='admin'?data.admins:data.warehouses).find(x=>x.id===id)}
function details(kind,id){const x=entity(kind,id);if(!x)return;const isHub=kind==='warehouse';const rows=isHub?[['Warehouse ID',x.id],['Location',x.location],['Address',x.address],['Status',x.status]]:[['Email address',x.email],['Phone number',x.phone],['Location',x.location||data.warehouses.find(w=>w.id===x.warehouse)?.name||'Unassigned'],['Joined on',date(x.joined)],...(kind==='admin'?[['Role',x.role]]:[['Customer ID',x.id]])];const team=isHub?data.admins.filter(a=>a.warehouse===id):[];openModal(isHub?'Warehouse details':kind==='admin'?'Administrator details':'Customer details','A closer look at your network.',`<div class="detail-identity">${avatar(x.name)}<div><h3>${esc(x.name)}</h3><p>${esc(x.id)} · ${esc(isHub?x.location:kind==='admin'?x.role:x.location)}</p></div><span style="margin-left:auto">${badge(x.status)}</span></div>${kind==='customer'?`<div class="detail-stats"><div><label>Lifetime value</label><strong>${money(x.value)}</strong></div><div><label>Total orders</label><strong>${x.orders}</strong></div><div><label>Member since</label><strong style="font-size:13px">${date(x.joined)}</strong></div></div>`:isHub?`<div class="detail-stats"><div><label>Stock on hand</label><strong>${number(x.stock)} kg</strong></div><div><label>Dispatched</label><strong>${x.dispatched}</strong></div><div><label>To be packed</label><strong>${x.packing}</strong></div></div>`:''}<div class="detail-list">${rows.map(([l,v])=>`<div><label>${esc(l)}</label><p>${esc(v)}</p></div>`).join('')}</div>${isHub?`<h3 style="font-size:13px;margin-bottom:12px">Assigned administrators (${team.length})</h3>${team.map((a,i)=>`<div class="person" style="margin-bottom:12px">${avatar(a.name,i)}<div><strong>${esc(a.name)}</strong><small>${esc(a.role)} · ${esc(a.status)}</small></div></div>`).join('')||'<p class="help-copy">No administrators assigned yet.</p>'}`:''}<div class="notice">${isHub?'Inventory and dispatch figures are sample snapshot values.':'This is a sample record. Changes are saved in this browser only.'}</div>`,`<button class="btn ${x.status==='Active'?'danger':''}" data-action="toggle" data-kind="${kind}" data-id="${id}">${x.status==='Active'?'Deactivate':'Activate'}</button><button class="btn primary" data-action="edit" data-kind="${kind}" data-id="${id}">${icon('edit')} Edit details</button>`)}
function editForm(kind,id){const x=id?entity(kind,id):{};const label=kind==='warehouse'?'warehouse':kind==='admin'?'administrator':'customer';const hubs=data.warehouses.filter(w=>w.status==='Active'||w.id===x.warehouse);let body=`<form id="entity-form" data-kind="${kind}" data-id="${id||''}">${field(kind==='warehouse'?'Warehouse name':'Full name','name',x.name)}${kind==='warehouse'?`${field('City and state','location',x.location)}<div class="field"><label for="field-address">Full address *</label><textarea id="field-address" name="address" required maxlength="400">${esc(x.address||'')}</textarea></div>`:`<div class="form-grid">${field('Email address','email',x.email,'email')}${field('Phone number','phone',x.phone,'tel')}</div>${kind==='admin'?`<div class="form-grid"><div class="field"><label for="field-role">Role *</label><select name="role" id="field-role"><option ${x.role==='Warehouse Admin'?'selected':''}>Warehouse Admin</option><option ${x.role==='Super Admin'?'selected':''}>Super Admin</option></select></div><div class="field"><label for="field-warehouse">Assigned warehouse *</label><select name="warehouse" id="field-warehouse" required><option value="">Select warehouse</option>${hubs.map(w=>`<option value="${w.id}" ${x.warehouse===w.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div></div>`:field('City and state','location',x.location)}`}${id?`<div class="field"><label for="field-status">Account status</label><select id="field-status" name="status"><option ${x.status==='Active'?'selected':''}>Active</option><option ${x.status==='Inactive'?'selected':''}>Inactive</option></select></div>`:''}<div class="notice">${kind==='admin'?'Creating an administrator adds a record to this workspace. It does not send an invitation or grant access to the live Veda Bharath site.':'This sample workspace saves changes in your browser.'}</div></form>`;openModal(`${id?'Edit':'New'} ${label}`,id?'Update the details below.':'Bring another part of your network into view.',body,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="entity-form">${icon('check')} ${id?'Save changes':kind==='admin'?'Create admin':'Add '+label}</button>`)}
function filterModal(){const kind=view==='admins'?'admin':view==='warehouses'?'warehouse':'customer';const locs=[...new Set((kind==='admin'?data.admins.map(a=>data.warehouses.find(w=>w.id===a.warehouse)?.location):kind==='warehouse'?data.warehouses:data.customers).map(x=>typeof x==='string'?x:x?.location).filter(Boolean))].sort();openModal('Filter directory','Find the people and places you need.',`<form id="filter-form"><div class="field"><label for="filter-location">Location</label><select id="filter-location" name="location"><option value="All">All locations</option>${locs.map(l=>`<option ${l===locationFilter?'selected':''}>${esc(l)}</option>`).join('')}</select></div><div class="field"><label for="filter-sort">Sort by</label><select id="filter-sort" name="sort"><option value="name" ${sort==='name'?'selected':''}>Name (A–Z)</option><option value="original" ${sort==='original'?'selected':''}>Original order</option>${kind==='customer'?`<option value="recent" ${sort==='recent'?'selected':''}>Recently joined</option><option value="value" ${sort==='value'?'selected':''}>Highest lifetime value</option>`:''}</select></div></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit" form="filter-form">Apply filters</button>`)}
function exportCSV(){let rows,name;if(view==='activity'){rows=[['Action','Description','Time'],...data.activity.map(a=>[a.title,a.description,a.time])];name='activity'}else if(view==='warehouses'){rows=[['ID','Warehouse','Location','Status','Stock kg','Dispatched','To be packed'],...filtered('warehouse').map(x=>[x.id,x.name,x.location,x.status,x.stock,x.dispatched,x.packing])];name='warehouses'}else if(view==='admins'){rows=[['ID','Administrator','Email','Role','Warehouse','Status'],...filtered('admin').map(x=>[x.id,x.name,x.email,x.role,data.warehouses.find(w=>w.id===x.warehouse)?.name||'',x.status])];name='administrators'}else{rows=[['ID','Customer','Email','Location','Orders','Lifetime value INR','Status','Joined'],...filtered('customer').map(x=>[x.id,x.name,x.email,x.location,x.orders,x.value,x.status,x.joined])];name='customers'}const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(/^[=+@\-\t\r]/.test(String(v))?"'"+v:v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`veda-bharath-${name}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV exported with the current filters.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,kind,id}=b.dataset;if(action==='navigate')navigate(b.dataset.view);if(action==='close')modal.close();if(action==='details')details(kind,id);if(action==='add'||action==='edit')editForm(kind,id);if(action==='export')exportCSV();if(action==='filters')filterModal();if(action==='status'){statusFilter=b.dataset.status;page=1;render()}if(action==='clear-filters'){query='';statusFilter='All';locationFilter='All';sort='name';page=1;render()}if(action==='page'){page=Number(b.dataset.page);render()}if(action==='profile'){openModal('Your profile','Workspace administrator',`<div class="detail-identity">${avatar('Sriraj Yadav')}<div><h3>Sriraj Yadav</h3><p>Super administrator · Sample profile</p></div></div><div class="detail-list"><div><label>Workspace</label><p>Veda Bharath · User Management</p></div><div><label>Role</label><p>Super Admin</p></div></div><div class="notice">This workspace is separate from the live Veda Bharath application.</div>`,`<button class="btn primary" data-action="close">Done</button>`)}if(action==='about'){openModal('About this workspace','A dedicated space for your network.',`<div class="help-copy"><p>Built from the Veda Bharath dashboard, design-system document and supplied logo.</p><p>The records are sample data. Additions and edits are saved in this browser; they do not update the original application or provision user accounts.</p><p>Search, filters, exports, warehouse assignments and profile updates work within this workspace. Open the bell to review changes.</p></div>`,`<button class="btn primary" data-action="close">Got it</button>`)}if(action==='toggle'){const x=entity(kind,id);const next=x.status==='Active'?'Inactive':'Active';if(kind==='warehouse'&&next==='Inactive'&&data.admins.some(a=>a.warehouse===id&&a.status==='Active')){toast('Reassign or deactivate this warehouse’s active administrators first.');return}if(kind==='admin'&&next==='Active'&&data.warehouses.find(w=>w.id===x.warehouse)?.status!=='Active'){toast('Assign this administrator to an active warehouse first.');return}openModal(`${next==='Inactive'?'Deactivate':'Activate'} ${esc(x.name)}?`,'This changes the sample record in this browser.',`<p class="help-copy">${next==='Inactive'?'The record will remain in the directory with an inactive status. You can reactivate it later.':'The record will be marked active in this workspace.'}</p>`,`<button class="btn" data-action="close">Cancel</button><button class="btn ${next==='Inactive'?'danger':'primary'}" data-action="confirm-toggle" data-kind="${kind}" data-id="${id}">Confirm ${next==='Inactive'?'deactivation':'activation'}</button>`)}if(action==='confirm-toggle'){const x=entity(kind,id);x.status=x.status==='Active'?'Inactive':'Active';modal.close();save(`${x.name} ${x.status==='Active'?'activated':'deactivated'}`,`${kind==='admin'?'Administrator':kind==='warehouse'?'Warehouse':'Customer'} status updated.`,kind==='warehouse'?'warehouse':'users')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;page=1;const caret=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();try{input.setSelectionRange(caret,caret)}catch{}}});
document.addEventListener('submit',e=>{if(e.target.id==='filter-form'){e.preventDefault();const f=new FormData(e.target);locationFilter=f.get('location');sort=f.get('sort');page=1;modal.close();render();return}if(e.target.id!=='entity-form')return;e.preventDefault();const form=e.target;const kind=form.dataset.kind,id=form.dataset.id;const f=Object.fromEntries(new FormData(form));for(const k in f)f[k]=f[k].trim();if(!f.name||((kind!=='warehouse')&&(!f.email||!f.phone))||(kind==='warehouse'&&(!f.location||!f.address))||(kind==='customer'&&!f.location)){toast('Please fill in all required fields.');return}const list=kind==='warehouse'?data.warehouses:kind==='admin'?data.admins:data.customers;if(kind!=='warehouse'&&list.some(x=>x.id!==id&&x.email.toLowerCase()===f.email.toLowerCase())){const email=form.elements.email;email.setCustomValidity('This email is already in the directory.');email.reportValidity();email.addEventListener('input',()=>email.setCustomValidity(''),{once:true});return}if(kind==='admin'&&f.status!=='Inactive'&&data.warehouses.find(w=>w.id===f.warehouse)?.status!=='Active'){toast('Select an active warehouse for an active administrator.');return}if(kind==='warehouse'&&f.status==='Inactive'&&data.admins.some(a=>a.warehouse===id&&a.status==='Active')){toast('Reassign or deactivate the active administrators before deactivating this warehouse.');return}if(id)Object.assign(entity(kind,id),f);else{const prefixes={warehouse:'WH',admin:'ADM',customer:'CUST'};const newId=prefixes[kind]+'-'+Date.now().toString().slice(-8);const base={id:newId,status:'Active',joined:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})};list.unshift({...base,...(kind==='warehouse'?{stock:0,dispatched:0,packing:0}:kind==='customer'?{orders:0,value:0}:{}),...f})}modal.close();save(`${f.name} ${id?'updated':'added'}`,`${kind==='warehouse'?'Warehouse':kind==='admin'?'Administrator':'Customer'} ${id?'details updated':'added to the workspace'}.`,kind==='warehouse'?'warehouse':'users')});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['overview','customers','warehouses','admins','activity'].includes(next)&&next!==view)navigate(next)});
render();
